import{_ as s,o as n,c as t,ag as e}from"./chunks/framework.D5hoimZQ.js";const k=JSON.parse('{"title":"PyPSA 基础模型原理（第二讲：LP/MILP 骨架）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/energysim/pypsa-base-model.md","filePath":"topics/energysim/pypsa-base-model.md"}'),p={name:"topics/energysim/pypsa-base-model.md"};function i(l,a,o,r,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="pypsa-基础模型原理-第二讲-lp-milp-骨架" tabindex="-1">PyPSA 基础模型原理（第二讲：LP/MILP 骨架） <a class="header-anchor" href="#pypsa-基础模型原理-第二讲-lp-milp-骨架" aria-label="Permalink to &quot;PyPSA 基础模型原理（第二讲：LP/MILP 骨架）&quot;">​</a></h1><blockquote><p>系列：EnergySim 代码带读 · 第二讲前置理解 对应代码：energysim-pyapi/helper/network.py + case_calc/caseinfo_calc_multi.py</p></blockquote><hr><h2 id="_1-基础模型从哪里来" tabindex="-1">1. 基础模型从哪里来 <a class="header-anchor" href="#_1-基础模型从哪里来" aria-label="Permalink to &quot;1. 基础模型从哪里来&quot;">​</a></h2><p>&quot;基础模型&quot; = PyPSA 根据 Network 里的组件<strong>自动生成的一套标准线性优化模型</strong>。不是手写的业务约束，是 PyPSA 自带的电力系统优化骨架。</p><p>代码里先把业务数据塞进 network：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network.import_components_from_dataframe(df_bus, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network.import_components_from_dataframe(df_line, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network.import_components_from_dataframe(df_generator, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Generator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network.import_components_from_dataframe(df_load, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Load&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network.import_components_from_dataframe(df_storage_unit, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;StorageUnit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>然后调 <code>network.lopf(...)</code>，PyPSA 根据这些组件自动建优化问题。</p><h2 id="_2-基础模型-变量-约束-目标函数" tabindex="-1">2. 基础模型 = 变量 + 约束 + 目标函数 <a class="header-anchor" href="#_2-基础模型-变量-约束-目标函数" aria-label="Permalink to &quot;2. 基础模型 = 变量 + 约束 + 目标函数&quot;">​</a></h2><h3 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>变量</th></tr></thead><tbody><tr><td>Generator</td><td>每个时刻发多少电 p[t]</td></tr><tr><td>Generator（可扩容）</td><td>装机容量 p_nom_opt</td></tr><tr><td>Load</td><td>通常固定负荷，不是变量</td></tr><tr><td>StorageUnit</td><td>充电功率 p_store[t] / 放电 p_dispatch[t] / 电量 state_of_charge[t]</td></tr><tr><td>Line</td><td>线路潮流 p0[t] / p1[t]</td></tr><tr><td>Link</td><td>转换功率 p0[t] / p1[t]</td></tr></tbody></table><h3 id="约束-pypsa-自动加" tabindex="-1">约束（PyPSA 自动加） <a class="header-anchor" href="#约束-pypsa-自动加" aria-label="Permalink to &quot;约束（PyPSA 自动加）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个母线每个时刻功率平衡</span></span>
<span class="line"><span>发电不能超过装机</span></span>
<span class="line"><span>新能源出力不能超过 p_max_pu</span></span>
<span class="line"><span>常规机组不能低于 p_min_pu</span></span>
<span class="line"><span>线路潮流不能超过容量</span></span>
<span class="line"><span>储能 SOC 动态平衡</span></span>
<span class="line"><span>储能功率不能超过 p_nom</span></span>
<span class="line"><span>储能电量不能超过 p_nom * max_hours</span></span>
<span class="line"><span>扩容容量不能超过 p_nom_min / p_nom_max</span></span></code></pre></div><h3 id="目标函数" tabindex="-1">目标函数 <a class="header-anchor" href="#目标函数" aria-label="Permalink to &quot;目标函数&quot;">​</a></h3><p>默认最小化总成本 = 投资成本 + 运行成本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum(装机容量 * capital_cost)</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>sum(每个时刻出力 * marginal_cost * 时间权重)</span></span></code></pre></div><p>时间权重 = <code>network.snapshot_weightings *= freq_hours</code>（小时分辨率放大系数）。</p><h2 id="_3-业务约束-vs-基础模型" tabindex="-1">3. 业务约束 vs 基础模型 <a class="header-anchor" href="#_3-业务约束-vs-基础模型" aria-label="Permalink to &quot;3. 业务约束 vs 基础模型&quot;">​</a></h2><p>基础模型是 PyPSA 自动有的。项目还有自己的规则（在 <code>extra_func/extra_fun_caseinfo.py</code> 手工追加）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全年下网电量不能超过上限</span></span>
<span class="line"><span>全年上网电量不能超过上限</span></span>
<span class="line"><span>新能源占负荷比例不能低于某个值</span></span>
<span class="line"><span>新能源利用率不能低于某个值</span></span>
<span class="line"><span>储能 SOC 不能低于 soc_min_pu</span></span>
<span class="line"><span>储能只能在指定小时充放电</span></span></code></pre></div><p><strong>最终求解模型</strong> = PyPSA 基础模型 + EnergySim 业务约束。</p><h2 id="_4-一句话理解" tabindex="-1">4. 一句话理解 <a class="header-anchor" href="#_4-一句话理解" aria-label="Permalink to &quot;4. 一句话理解&quot;">​</a></h2><blockquote><p>基础模型 = 在每个时刻，让发电、负荷、储能、线路、转换器满足<strong>能量平衡</strong>和<strong>设备能力限制</strong>，同时让<strong>总成本最低</strong>。 项目自己的 extra_func 在此基础上加：年度指标、比例指标、储能时段、SOC 规则。</p></blockquote><h2 id="_5-最小例子" tabindex="-1">5. 最小例子 <a class="header-anchor" href="#_5-最小例子" aria-label="Permalink to &quot;5. 最小例子&quot;">​</a></h2><p>一个母线 + 一个光伏 + 一个负荷 + 一个储能 + 一个电网下网：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每小时:  光伏出力 + 电网下网 + 储能放电 = 负荷 + 储能充电</span></span>
<span class="line"><span>光伏出力 &lt;= 光伏装机 * 光伏可发比例</span></span>
<span class="line"><span>电网下网 &lt;= 下网容量</span></span>
<span class="line"><span>储能充电 &lt;= 储能功率</span></span>
<span class="line"><span>储能放电 &lt;= 储能功率</span></span>
<span class="line"><span>SOC[t] = SOC[t-1] + 充电 - 放电 - 损耗</span></span></code></pre></div><p>最小化：买电成本 + 设备投资成本 - 上网收益。</p><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/energysim/">EnergySim 项目地图</a></li><li><a href="/zhishiku-reading/topics/energysim/lopf-main-chain.html">第一讲 LOPF 主链路</a></li></ul>`,29)])])}const u=s(p,[["render",i]]);export{k as __pageData,u as default};
